--
-- Table structure for table `data`
--

DROP TABLE IF EXISTS `data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `data` (
  `slug` varchar(255) NOT NULL,
  `title` varchar(255) NOT NULL,
  `cover` varchar(500) DEFAULT '',
  `cover_notion` varchar(500) DEFAULT '',
  `url_seo_yandex` varchar(500) DEFAULT NULL,
  `url_seo_google` varchar(500) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `author_slug` varchar(255) DEFAULT '',
  `status_slug` varchar(255) DEFAULT '',
  `group_slug` varchar(255) NOT NULL,
  `subgroup_slug` varchar(255) NOT NULL,
  `url_title_1` varchar(255) DEFAULT '',
  `url_1` varchar(500) DEFAULT NULL,
  `url_title_2` varchar(255) DEFAULT '',
  `url_2` varchar(500) DEFAULT NULL,
  `url_title_3` varchar(255) DEFAULT '',
  `url_3` varchar(500) DEFAULT NULL,
  `url_title_4` varchar(255) DEFAULT '',
  `url_4` varchar(500) DEFAULT NULL,
  `url_title_5` varchar(255) DEFAULT '',
  `url_5` varchar(500) DEFAULT NULL,
  `url_title_6` varchar(255) DEFAULT '',
  `url_6` varchar(500) DEFAULT NULL,
  `start_date` varchar(255) DEFAULT '',
  `end_date` varchar(255) DEFAULT '',
  `published` varchar(255) DEFAULT '',
  `created_at` varchar(255) DEFAULT '',
  `updated_at` varchar(255) DEFAULT '',
  `summary_ai` text DEFAULT NULL,
  `detail` text DEFAULT NULL,
  `comment` text DEFAULT NULL,
  `version_slug` varchar(255) DEFAULT NULL,
  `created_at_db` timestamp NULL DEFAULT current_timestamp(),
  `updated_at_db` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`slug`),
  KEY `idx_slug` (`slug`),
  KEY `idx_group_slug` (`group_slug`),
  KEY `idx_subgroup_slug` (`subgroup_slug`),
  KEY `idx_status_slug` (`status_slug`),
  KEY `idx_group_subgroup` (`group_slug`,`subgroup_slug`),
  KEY `fk_data_version` (`version_slug`),
  CONSTRAINT `data_ibfk_1` FOREIGN KEY (`group_slug`) REFERENCES `groups` (`slug`) ON DELETE CASCADE,
  CONSTRAINT `data_ibfk_2` FOREIGN KEY (`subgroup_slug`) REFERENCES `subgroups` (`slug`) ON DELETE CASCADE,
  CONSTRAINT `fk_data_version` FOREIGN KEY (`version_slug`) REFERENCES `versions` (`slug`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
