INSERT INTO `groups` VALUES ('books','Книги','books','❇️ Новый раздел','images/groups/book.webp','https://gdozktobkosdlddavthj.supabase.co/storage/v1/object/public/service/new-book.webp','Читай и размышляй','Подборка книг для дизайнеров: мышление, креатив, UX/UI, визуальный стиль. Читай и развивайся.','книги по дизайну, книги UX/UI, подборка дизайнерских книг','Вдохновляйся идеями и прокачивай вкус через книги о дизайне и мышлении.','images/groups/book.webp','Книги по дизайну — Библиотечка',7,'Лучшие книги по дизайну и креативу — Библиотечка','2025-12-13 19:09:20','2025-12-13 19:09:20'),('community','Сообщество','community','','images/groups/community.webp','https://gdozktobkosdlddavthj.supabase.co/storage/v1/object/public/service/new-community.webp','Блоги и конференции','Вдохновляйся опытом коллег: подборки блогов, встречи и дизайнерские конференции.','сообщество дизайнеров, дизайн конференции, UI/UX блоги','Мир общения, идей и поддержки дизайнеров — будь в профессиональном кругу.','images/groups/community.webp','Сообщество дизайнеров — Библиотечка',6,'Сообщество дизайнеров — блоги, конференции, события','2025-12-13 19:09:20','2025-12-13 19:09:20'),('designsystem','Дизайн-система','designsystem','','images/groups/designsystem.webp','https://gdozktobkosdlddavthj.supabase.co/storage/v1/object/public/service/new-designsystem.webp','Компоненты, гайдлайны, брендбуки','Научись разрабатывать дизайн-системы: компоненты, принципы, брендбуки и лучшие практики.','дизайн-система, компоненты, брендбук, UI kit','Узнай, как выстроить единую экосистему бренда с помощью дизайн-системы.','images/groups/designsystem.webp','Создание и поддержка дизайн-системы — Библиотечка',4,'Как создать и поддерживать дизайн-систему — гайд и примеры','2025-12-13 19:09:20','2025-12-13 19:09:20'),('life','Жизнь','life','❇️ Новый раздел','images/groups/life.webp','https://gdozktobkosdlddavthj.supabase.co/storage/v1/object/public/service/new-life.webp','Быт, здоровье и советы','Практичные советы про быт, здоровье, баланс и вдохновение для каждой сферы жизни.','советы по жизни, саморазвитие, здоровье, баланс, мотивация','Идеи и лайфхаки для здоровой, осознанной и гармоничной жизни.','images/groups/life.webp','Советы по жизни — Библиотечка',8,'Советы по жизни и саморазвитию — Библиотечка','2025-12-13 19:09:20','2025-12-13 19:09:20'),('reference','Насмотренность','reference','','images/groups/reference.webp','https://gdozktobkosdlddavthj.supabase.co/storage/v1/object/public/service/new-reference.webp','Референсы на все темы','Подборка авторских и профессиональных референсов для расширения визуального кругозора.','насмотренность, референсы, вдохновение дизайнеров','Смотри, анализируй, вдохновляйся и развивай вкус через лучшие визуальные проекты.','images/groups/reference.webp','Прокачка насмотренности — Библиотечка',2,'Прокачай насмотренность — референсы и вдохновение','2025-12-13 19:09:20','2025-12-13 19:09:20'),('resource','Ресурсы','resource','','images/groups/resource.webp','https://gdozktobkosdlddavthj.supabase.co/storage/v1/object/public/service/new-resource.webp','Графические плюшки и арт','Полезные графические ресурсы, шрифты, иконки и mockup-файлы для дизайна любого уровня.','ресурсы для дизайнеров, графические материалы, бесплатные mockup','Коллекция графических файлов и арт-материалов для твоих дизайн-проектов.','images/groups/resource.webp','Ресурсы для дизайнеров — Библиотечка',5,'Материалы и ресурсы для дизайнеров — Библиотечка','2025-12-13 19:09:20','2025-12-13 19:09:20'),('skill','Навыки','skill','','images/groups/skill.webp','https://gdozktobkosdlddavthj.supabase.co/storage/v1/object/public/service/new-skill.webp','Для развития скиллов','Хочешь стать лучше в UX/UI? Инструменты, упражнения и материалы для роста профессиональных навыков.','развитие UX/UI, навыки дизайнера, UX/UI курсы, UI тренировки','Всё, что нужно, чтобы уверенно развивать скиллы и выходить на новый уровень.','images/groups/skill.webp','Развитие UX/UI навыков — Библиотечка',1,'Развитие UX/UI навыков — советы и курсы','2025-12-13 19:09:20','2025-12-13 19:09:20'),('trainer','Тренажёры','trainer','','images/groups/trainer.webp','https://gdozktobkosdlddavthj.supabase.co/storage/v1/object/public/service/new-trainer.webp','Игры, брифы, челленджи','Прокачай UX/UI через практику: интерактивные тренажёры, брифы, челленджи и дизайн-баттлы.','UX тренажёры, UI челленджи, дизайн практика','Практикуйся, решай кейсы и повышай уровень дизайна в игровой форме.','images/groups/trainer.webp','UX/UI тренажёры — Библиотечка',3,'UX/UI тренажёры — игры и челленджи для дизайнеров','2025-12-13 19:09:20','2025-12-13 19:09:20');
