INSERT INTO `versions` VALUES ('1','1.0','Первый релиз','Начало. MVP','August 27, 2024','https://t.me/productorial/361','2025-12-13 19:11:01','2025-12-13 19:12:30'),('10','5.0','Редизайн сервиса','Добрые духи передали, что надо оплатить за хостинг и вернуть сервис к жизни. Я конечно денюжку закинул и заодно завёз новый мимишный дизайн ‼️, чего уж его держать у себя и не делиться!','November 26, 2025','https://t.me/productorial/550','2025-12-13 19:11:01','2025-12-13 19:12:30'),('2','2.0','Обновление контента','Прибрался во всех категориях, убрал лишнее. В каждой карточке теперь есть основная ссылка и ещё 3 полезные + заголовки к каждому урлу, чтобы совсем не гадать. А ещё аи обложки, удобные вью галереи и навигация в карточках','October 25, 2024','https://t.me/productorial/394','2025-12-13 19:11:01','2025-12-13 19:12:30'),('3','2.1','Расширение категорий','Добавил очередную партию годноты для развития насмотренности: от классического веба и SaaS до пушей, презентаций, рассылок, постеров, шоурилов и много другого','November 11, 2024','https://t.me/productorial/403','2025-12-13 19:11:01','2025-12-13 19:12:30'),('4','2.2','Добавление контента','- Новый кайфовый домен, вы только посмотрите: Библиотечка.рф\n- Добавил много полезных карточек, затронул категории: насмотренность, SDUI, основы дизайна, игры, программы, ДС, библиотеки шрифтов. Скоро пробьём отметку в 300 полезностей, присылайте находки!\n- Добавил ссылку для донатов. Можно и по СБП, всё прозрачно','January 6, 2025','https://t.me/productorial/430','2025-12-13 19:11:01','2025-12-13 19:12:30'),('5','3.0','Переезд на Notion','Переход на Notion и неудачные попытки построить сайт с backend на Vercel. Также добавил много материалов','May 8, 2025','https://t.me/productorial/480','2025-12-13 19:11:01','2025-12-13 19:12:30'),('6','3.1','Много новых карточек','Провёл глобальную уборку, удалил много лишних карточек, полей данных и заодно обогатил недостающие сведения в существующих.\nТеперь еще больше инфы: новые рефы по вебу, сторонние базы знаний, вайтборды, инструменты, дизайн-системы и многое другое. Смотрите «Что нового» на главной странице, там сгруппировано по релизам. Также появился новый раздел «Навыки», в котором хранятся материалы для саморазвития','June 18, 2025','https://t.me/productorial/488','2025-12-13 19:11:01','2025-12-13 19:12:30'),('7','3.2','Много новых карточек','+94 карточки, такие тщательно отобранные для ваших рабочих и селфкейр будней\n• Новые 2 раздела: книги и жизнь. Книги — это вечная классика, даже если интернет выключат, кладезь витаминов. Жизнь — это попытка сохранить полезное нерабочее, о нашем здоровье и быте, пока что там немного, но всё будет, дайте время и сами предлагайте\n• Ушел я от аишных обложек, теперь рентгенки','August 12, 2025','https://t.me/productorial/491','2025-12-13 19:11:01','2025-12-13 19:12:30'),('8','4.0','Новый сайт','Ну что, свершилось! Библиотечка обрела свой сайт, на энтузиазме и получистом вайбкоде чатгпт. Ручками много правил, но это и нормально\n\nПочему свой сайт, а не ноушн или фреймер/вебфлоу? \nПотому что я поставил себе челлендж написать с ИИ рабочую версию с нуля, занести свой дизайн и создать платформу для будущих экспериментов, а планы есть!\n\nГоржусь, что теперь всем доступна навигация с якорными ссылками и описанием подгрупп + несколько фишек. Всё чекается Яндекс Метрикой. Прошло 2 суток, DNS должен был у всех обновиться и более не перекидывать в ноушн','September 27, 2025','https://t.me/productorial/516','2025-12-13 19:11:01','2025-12-13 19:12:30'),('9','4.1','Устранение бага','Недавно полез искать конкретную карточку в Библиотечке и смотрю что-то мало информации. Вроде всё на месте, но что-то не так... 🤔 \n\nНачал раскапывать и выяснил, что с момента релиза при переходе в разделы фронт искусственно скрывал суммарно 89 карточек, потому что не совпадали параметры между базами данных\n\n▶️ Но хорошо, что нашел проблему, все починил и заодно заредизайнил главную (как по кайфу), теперь она адаптивна, ничего не скрывается за скроллом. Класс!','October 20, 2025','https://t.me/productorial/530','2025-12-13 19:11:01','2025-12-13 19:12:30');
